examples.code:
X = [1 2; 1.3 1.8; 0.8 2.4; 5 5; 5.5 4.9; 4.6 5.3; 9 1; 9.2 1.5];
[idx, C] = kmeans(X, 2, 'Replicates', 5);
disp(size(idx))
disp(size(C))
disp(sort(unique(idx))')

D = pdist([0 0; 3 0; 0 4]);
[Y, e] = cmdscale(D);
disp(round(abs(Y)*1000)/1000)
disp(round(e'*1000)/1000)

A = [2 4 1; 3 5 2; 5 8 3; 4 7 2; 6 9 5; 7 12 4];
[coeff, score, latent, tsquared, explained, mu] = pca(A);
disp(round(latent'*1000)/1000)
disp(round(explained'*100)/100)
disp(mu)

A = [2 4 1; 3 5 2; 5 8 3; 4 7 2; 6 9 5; 7 12 4];
[coeff, latent, explained] = pcacov(cov(A));
disp(round(latent'*1000)/1000)
disp(round(explained'*100)/100)

S = [4 0; 0 1];
[coeff, latent, explained] = pcacov(S);
disp(abs(coeff))
disp(latent')
disp(explained')

A = [2 4 1; 3 5 2; 5 8 3; 4 7 2; 6 9 5; 7 12 4];
[residuals, reconstructed] = pcares(A, 1);
disp(round(residuals*1000)/1000)
disp(round(max(abs(A - reconstructed - residuals),[],'all')*1e6)/1e6)

A = [2 4 1; 3 5 2; 5 8 3; 4 7 2; 6 9 5; 7 12 4];
for k = 0:3
  r = pcares(A, k);
  fprintf('%d %.4f\n', k, norm(r, 'fro'));
end

X = [0 0; 1 0; 1 1; 0 1; 0.5 2];
th = pi/6;
R = [cos(th) -sin(th); sin(th) cos(th)];
Y = 2*X*R + [3 -1];
[d, Z, tr] = procrustes(X, Y);
fprintf('%.6f\n', d)
disp(round(Z*1000)/1000)
fprintf('%.4f\n', tr.b)

[h, p, stats] = fishertest([3 1; 1 3]);
fprintf('%d %.4f\n', h, p)
fprintf('%.4f\n', stats.OddsRatio)

Y = [10 14 12; 8 9 11; 12 15 13; 7 10 9; 11 13 14; 9 8 12];
[p, tbl, stats] = friedman(Y, 1, 'off');
fprintf('p = %.4f\n', p)
disp(tbl{2,5})
disp(stats.meanranks)

y = [2.1 3.4 1.9 5.6 4.8 6.1 7.2 8.8 6.9]';
g = [1 1 1 2 2 2 3 3 3]';
[p, tbl, stats] = kruskalwallis(y, g, 'off');
fprintf('p = %.4f\n', p)
disp(stats.meanranks)

M = [2.1 5.6 7.2; 3.4 4.8 8.8; 1.9 6.1 6.9];
[p, tbl] = kruskalwallis(M, [], 'off');
fprintf('chi-square = %.4f, p = %.4f\n', tbl{2,5}, p)

s = (-7:7)'/4;
[h, p, ksstat, cv] = kstest(s);
fprintf('%d %.4f %.4f %.4f\n', h, p, ksstat, cv)

s = (-7:7)'/4;
[h, p] = kstest(s + 3);
fprintf('%d %.3g\n', h, p)
[h, p] = kstest(s, 'CDF', [s normcdf(s, 0.5, 1)]);
fprintf('%d %.4f\n', h, p)

a = [1.1 2.3 3.2 4.8 5.1 6.7 7.4];
b = [3.5 4.1 5.9 6.3 8.2 9.1 9.9 10.4];
[p, h, stats] = ranksum(a, b, 'method', 'approximate');
fprintf('%.4f %d\n', p, h)
fprintf('%.4f\n', stats.zval)

x = [1 0 1 1 0 0 1 0 1 1 1 0 0 1 0 0 0 1 1 0];
[h, p, stats] = runstest(x, 0.5);
fprintf('%d %.4f\n', h, p)
disp(stats.nruns)

x = sin(1:30);
[h, p, stats] = runstest(x);
fprintf('%d %.4f\n', h, p)
fprintf('%d runs, z = %.4f\n', stats.nruns, stats.z)

bef = [125 115 130 140 140 115 140 125 140 135];
aft = [110 122 125 120 140 124 123 137 135 145];
[p, h, stats] = signrank(bef - aft, 0, 'method', 'approximate');
fprintf('%.4f %d\n', p, h)
fprintf('%.4f\n', stats.zval)
